#!/bin/bash
#flux: --job-name=trim
#flux: --time=10:00:00
#flux: --nodes=1
#flux: --ntasks=24
# Based on validator feedback from a previous attempt, several directives were omitted or changed:
# - Account ('-A phillipslab')
# - Partition ('--partition=phillips')
# - The request for 1 task with 24 CPUs has been simplified to 24 total tasks, as the per-task
#   CPU directive was rejected. This assumes the environment is configured such that the '--ntasks'
#   request provides the necessary core count to the multi-threaded application.
# --
# CRITICAL PERFORMANCE IMPLICATION:
# The application 'skewer' is launched as a single process, but it is expected to use 24 threads (`-t 24`).
# However, the job requests 24 separate task slots. This mismatch can lead to incorrect CPU binding and poor
# performance, as the single process may be confined to one core while leaving 23 others idle.

export OMP_NUM_THREADS=${FLUX_JOB_NTASKS:-1}

module load easybuild  icc/2017.1.132-GCC-6.3.0-2.27  impi/2017.1.132 skewer

outd="/projects/phillipslab/ateterina/CR_map/FINAL"

cd /projects/phillipslab/ateterina/CR_map/FINAL
cat Barcodes_Well_EcoR1_Stacks_names.txt |cut -f1 - >ALL_ECOI_BARCODES.txt

split -l 1  ALL_ECOI_BARCODES.txt indbarcode --additional-suffix=.txt

for i in {0..96};do
	barc=$(ls ind*);
	id=$(echo {A..H}{01..12}.barcode.fasta);
	arr=($barc);
	arr2=($id);
	echo ${arr2[$i]};cp ${arr[$i]} ${arr2[$i]};
done

for i in *barcode.fasta;do
	name=${i/.fasta//};
	sed -i "1 i\>$name" $i;
done

mkdir BARCODES
mv *barcode.fasta BARCODES/
rm indbarcode*

for DIR in A1 A2 B1 B2;do
	cd $outd/stacks/$DIR;

	for i in {A..H}{01..12};do
		echo "skewer removes barcodes from ...";
		echo $i;
		skewer -y $outd/BARCODES/$i.barcode.fasta -t 24 -l 36 -r 0.01 -d 0.01  -o ${i}.filt ${i}.1.fq ${i}.2.fq;
		echo "done!";
	done

	for i in *fastq;do
		 mv $i ${i/filt-trimmed-pair/fp};
	done

	mkdir -p RAW
	mv *fq RAW

done

